window.ScripturaLexicons.BDAG_PART_0381 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-01\" data-source=\"BDAG\" data-search=\"φραγ- elemento de composição; remissão v. φράσσω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φραγ-</td><td>elemento de composição; remissão</td><td>v. φράσσω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-02\" data-source=\"BDAG\" data-search=\"φραγέλλιον, ου, τό substantivo neutro chicote; açoite BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φραγέλλιον, ου, τό</td><td>substantivo neutro</td><td>chicote; açoite</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-03\" data-source=\"BDAG\" data-search=\"φραγελλόω verbo açoitar; flagelar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φραγελλόω</td><td>verbo</td><td>açoitar; flagelar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-04\" data-source=\"BDAG\" data-search=\"φραγμός, οῦ, ὁ substantivo masculino cerca; sebe; divisória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φραγμός, οῦ, ὁ</td><td>substantivo masculino</td><td>cerca; sebe; divisória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-05\" data-source=\"BDAG\" data-search=\"φράζω verbo explicar; interpretar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φράζω</td><td>verbo</td><td>explicar; interpretar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-06\" data-source=\"BDAG\" data-search=\"φράσσω verbo fechar; calar; impedir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φράσσω</td><td>verbo</td><td>fechar; calar; impedir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-07\" data-source=\"BDAG\" data-search=\"φρέαρ, ατος, τό substantivo neutro poço; abismo; cavidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρέαρ, ατος, τό</td><td>substantivo neutro</td><td>poço; abismo; cavidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-08\" data-source=\"BDAG\" data-search=\"φρεναπατάω verbo enganar; induzir em erro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρεναπατάω</td><td>verbo</td><td>enganar; induzir em erro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-09\" data-source=\"BDAG\" data-search=\"φρεναπάτης, ου, ὁ substantivo masculino enganador; impostor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρεναπάτης, ου, ὁ</td><td>substantivo masculino</td><td>enganador; impostor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-10\" data-source=\"BDAG\" data-search=\"φρήν, φρενός, ἡ substantivo feminino pensamento; entendimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρήν, φρενός, ἡ</td><td>substantivo feminino</td><td>pensamento; entendimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-11\" data-source=\"BDAG\" data-search=\"φρίκη, ης, ἡ substantivo feminino estremecimento; arrepio de medo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρίκη, ης, ἡ</td><td>substantivo feminino</td><td>estremecimento; arrepio de medo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-12\" data-source=\"BDAG\" data-search=\"φρίσσω verbo tremer de medo; estremecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρίσσω</td><td>verbo</td><td>tremer de medo; estremecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-13\" data-source=\"BDAG\" data-search=\"φρονέω verbo pensar; julgar; dedicar atenção; estar disposto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρονέω</td><td>verbo</td><td>pensar; julgar; dedicar atenção; estar disposto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-14\" data-source=\"BDAG\" data-search=\"φρόνημα, ατος, τό substantivo neutro modo de pensar; intenção; aspiração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρόνημα, ατος, τό</td><td>substantivo neutro</td><td>modo de pensar; intenção; aspiração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-15\" data-source=\"BDAG\" data-search=\"φρόνησις, εως, ἡ substantivo feminino disposição mental; entendimento; inteligência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρόνησις, εως, ἡ</td><td>substantivo feminino</td><td>disposição mental; entendimento; inteligência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-16\" data-source=\"BDAG\" data-search=\"φρόνιμος, ον adjetivo sensato; prudente; sábio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρόνιμος, ον</td><td>adjetivo</td><td>sensato; prudente; sábio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-17\" data-source=\"BDAG\" data-search=\"φρονίμως advérbio prudentemente; sagazmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φρονίμως</td><td>advérbio</td><td>prudentemente; sagazmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-18\" data-source=\"BDAG\" data-search=\"φροντίζω verbo refletir; cuidar; empenhar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φροντίζω</td><td>verbo</td><td>refletir; cuidar; empenhar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-19\" data-source=\"BDAG\" data-search=\"φροντίς, ίδος, ἡ substantivo feminino reflexão; pensamento; cuidado; preocupação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φροντίς, ίδος, ἡ</td><td>substantivo feminino</td><td>reflexão; pensamento; cuidado; preocupação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0381-20\" data-source=\"BDAG\" data-search=\"φροντιστής, οῦ, ὁ substantivo masculino protetor; guardião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">φροντιστής, οῦ, ὁ</td><td>substantivo masculino</td><td>protetor; guardião</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0381-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγ-</h1><div class=\"entry-meta\"><span>elemento de composição; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φραγ</span>- v. <span class=\"greek\">φράσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγέλλιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φραγέλλιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (empréstimo do lat.: flagellum [Horácio, Sat. 1, 3, 119 horribile flagellum], constituído de uma ou mais correias, frequentemente com pontas metálicas para aumentar a severidade da punição. Na forma <span class=\"greek\">φλαγέλλιον</span> PLond II, 191, 11 p. 265 [II d.C.]; CWessely, WienerStud 24, 1902 p. 150. Empréstimo na literatura rabínica. B-D-F §5, 1b; 41, 2; Mlt-H. 103; 396; Hahn 261; 265. A grafia <span class=\"greek\">φραγέλλιον</span> [assim p. ex. SEG XLII, 1240, 4] encontra-se somente em fontes muito tardias) chicote, açoite feito de cordas (muito menos letal que o ‘flagellum’ penal, v. verbete seguinte) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:15.</a>—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγελλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φραγελλόω</span> (<span class=\"greek\">φραγγέλιον</span>; em uso cristão [v. final deste verbete]; mas cf. TestBenj 2:3 e Esopo do Cod. Paris. 1277: CRochefort, Notices et Extraits II [1789] 719 n.º 19) 1.º aor. <span class=\"greek\">ἐφραγέλλωσα</span> (empréstimo do lat.: flagello; v. <span class=\"greek\">φραγέλλιον</span>) açoitar, flagelar, punição infligida a escravos e provincianos depois de pronunciada contra eles uma sentença de morte. Assim no caso de Jesus antes da crucificação (cf. Jos., Bell. 2, 306 <span class=\"greek\">οὓς</span> <span class=\"greek\">μάστιξιν</span> <span class=\"greek\">προαικισάμενος</span> <span class=\"greek\">ἀνεσταύρωσεν</span> [a saber, <span class=\"greek\">Φλῶρος</span>]; 5, 449; Lucian, Pisc. 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:15</a> (Mommsen, Röm. Strafrecht 1899, 938f; 983f; RAC IX, 469–90; contraste-se a ação em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:16</a> <span class=\"greek\">παιδεύω</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:1</a> <span class=\"greek\">μαστιγόω</span>). Executada após sentença de combate com animais AcPl Ha 1, 30.—RGundry, Mark ’93, 938f (referências). DELG s.v. <span class=\"greek\">φραγέλλιον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φραγμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φραγμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">φράσσω</span>; Soph., Hdt.+; BGU 1119, 32 [5 a.C.]; POxy 580; LXX, Philo)</p><p class=\"entry-text\">① estrutura para delimitar uma área, cerca, sebe, lit. (Theocr. 5, 108 a cerca em torno da vinha) <span class=\"greek\">περιέθηκεν</span> <span class=\"greek\">φραγμόν</span> (Is 5:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:1</a>; com dat. do terreno cercado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33.</a> <span class=\"greek\">ἄμπελος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φραγμῷ</span> <span class=\"greek\">τινι</span> <span class=\"greek\">καταλειφθεῖσα</span> uma videira abandonada em algum ponto ao longo da cerca Hs 9, 26, 4. Vagabundos e mendigos frequentam as sebes e cercas em torno das casas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:23.</a></p><p class=\"entry-text\">② muro que separa, divisória, extensão fig. de 1, da lei, que separa os circuncidados dos incircuncisos, os israelitas dos não israelitas, e suscita inimizade entre eles <span class=\"greek\">τὸ</span> <span class=\"greek\">μεσότοιχον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φραγμοῦ</span> Eph 2:14 (v. <span class=\"greek\">μεσότοιχον</span> e PFeine, Eph 2:14–16: StKr 72, 1899, 540–74; comentários).—DELG s.v. <span class=\"greek\">φράσσω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φράζω</span> fut. 1.ª pl. <span class=\"greek\">φράσομεν</span>; 1.º aor. <span class=\"greek\">ἔφρασα</span>, imperat. <span class=\"greek\">φράσον</span> (Hom. +) em nossa literatura somente no sentido de explicar, interpretar algo misterioso (X., Oec. 16, 8; Cebes 33, 1; Herm. Wr. 380, 2 Sc. <span class=\"greek\">θεόν</span>; Job 6:24 <span class=\"greek\">φράσατέ</span> <span class=\"greek\">μοι</span>) uma parábola <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:36</a> v.l. (por <span class=\"greek\">διασάφησον</span>); 15:15.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φράσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φράσσω</span> 1.º aor. <span class=\"greek\">ἔφραξα</span>. Pass.: 2.º fut. <span class=\"greek\">φραγήσομαι</span>; 2.º aor. <span class=\"greek\">ἐφράγην</span>; perf. 3.ª sg. <span class=\"greek\">πέφρακται</span> (Just.) (Hom. e outros; ins, pap, LXX; Jos., Bell. 3, 384; Just., D. 12, 2; 33, 1)</p><p class=\"entry-text\">① fechar ou impedir de abrir, cerrar, fechar</p><p class=\"entry-text\">ⓐ lit. (Herodian 8, 1, 6; Lucian, Nigrin. 19 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">κηρῷ</span> <span class=\"greek\">φρ</span>.) <span class=\"greek\">στόματα</span> <span class=\"greek\">λεόντων</span> bocas de leões, de modo que não possam causar dano (cf. Da 6:17ff; v. 23 Theod. <span class=\"greek\">ἐνέφραξεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">στόματα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λεόντων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:33.</a></p><p class=\"entry-text\">ⓑ extensão fig. de 1a: fechar ou tapar a boca, de modo que a pessoa tenha de permanecer em silêncio (Galen, Script. Min. I p. 73, 17 Marquardt; SibOr 8, 420 <span class=\"greek\">στόμα</span> <span class=\"greek\">ἔφραξαν</span>; 1 Macc 9:55 <span class=\"greek\">ἀπεφράγη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">αὐτοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19.</a> Este sentido pode ser o correto para <span class=\"greek\">ἡ</span> <span class=\"greek\">καύχησις</span> <span class=\"greek\">αὕτη</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">φραγήσεται</span> esta jactância não será silenciada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:10.</a> Mas <span class=\"greek\">φράσσω</span> também significa</p><p class=\"entry-text\">② fazer cessar algo, bloquear, impedir (Thu. 4, 13, 4 <span class=\"greek\">φράξαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἔσπλους</span>; Dio Chrys. 19 [36], 2 pass.); nesse caso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:10</a> significa esta jactância não será (não se deixará) suprimir (passiva permissiva, Gildersleeve I §168).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρέαρ, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρέαρ</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom. Hymns, Hdt. e outros; ins, pap, LXX; TestAbr A 3 p. 80, 1 e 4 [Stone p. 8]; Philo)</p><p class=\"entry-text\">① construção constituída de uma abertura vertical, coberta com uma pedra, para abastecimento de água, um poço (Appian, Bell. Civ. 4, 107 §448; Arrian, Anab. 6, 18, 1; 6, 20, 4; Jos., Ant. 4, 283 <span class=\"greek\">οἱ</span> <span class=\"greek\">φρέαρ</span> <span class=\"greek\">ὀρύξαντες</span>; Philo, Somn. 1, 8 [segundo Gen 26:32].—Contraste: <span class=\"greek\">πηγή</span> … <span class=\"greek\">φρέαρ</span> Paus. 1, 14; Philo, Poster. Cai. 153) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:5</a> (Aesop, Fab. 9 P.=45a H.; 40 Ch.; 9 H-H. <span class=\"greek\">ἀλώπηξ</span> <span class=\"greek\">πεσοῦσα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φρέαρ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:11</a> (Gen 21:19 <span class=\"greek\">φρέαρ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ζῶντος</span>; 26:19), 12 (Hom. Hymns, Demeter 98f o motivo do viajante divino que se senta perto da cidade <span class=\"greek\">φρέατι</span>, <span class=\"greek\">ὅθεν</span> <span class=\"greek\">ὑδρεύοντο</span> <span class=\"greek\">πολῖται</span>). O jogo de palavras <span class=\"greek\">πηγή</span> … <span class=\"greek\">φρέαρ</span> prepara o terreno para o dito nos vv. 13f, e a mudança para <span class=\"greek\">φρέαρ</span> no v. 11 é feita para pôr em relevo a profundidade da abertura vertical (v. 2 abaixo), que exige o uso de um balde. Em contraste, Jesus fornece água que ‘jorra’ v. 14 (v. <span class=\"greek\">ἄλλομαι</span> 2).</p><p class=\"entry-text\">② abertura que conduz às profundezas do mundo inferior, fosso, abertura vertical (para o sentido ‘abertura vertical’ v. Hero Alex. I p. 32, 12; 15; v. também <span class=\"greek\">ἄβυσσος</span> 2; cf. Ps 54:24 <span class=\"greek\">φρέαρ</span> <span class=\"greek\">διαφθορᾶς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:1,</a> 2abc.—B. 44. DELG. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεναπατάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρεναπατάω</span> (em uso cristão; Hesych.; mas v. <span class=\"greek\">φρεναπάτης</span>) induzir em erro quanto à verdade, enganar <span class=\"greek\">ἑαυτόν</span> a si mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:3.</a>—DELG s.v. <span class=\"greek\">ἀπάτη</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρεναπάτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρεναπάτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">φρήν</span>, <span class=\"greek\">ἀπάτη</span>, cf. verbete anterior; Herodian Gr. II 848, 27; PGrenf I, 1, 10 [II a.C.]=Coll. p. 178 linha 18; v. UvWilamowitz, NGG 1896, 209 ff; PLond V, 1677, 22 [VI d.C.]) enganador, aquele que induz em erro (com <span class=\"greek\">ματαιολόγος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:10.</a>—Cf. DELG s.v. <span class=\"greek\">ἀπάτη</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρήν, φρενός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρήν</span>, <span class=\"greek\">φρενός</span>, <span class=\"greek\">ἡ</span> pl. <span class=\"greek\">αἱ</span> <span class=\"greek\">φρένες</span> (principalmente pl. e em vários sentidos: Hom. e outros; ins, pap, LXX, TestSol, Philo) em nossa literatura somente em uma passagem e somente no pl. como processo de consideração cuidadosa, pensamento, entendimento (Hom. e outros; Plut., Mor. 116b <span class=\"greek\">φρένας</span> <span class=\"greek\">ἔχειν</span>; Herm. Wr. 13, 4; 5; Pr 7:7; 9:4 e outros lugares; Jos., Ant. 10, 114 <span class=\"greek\">ἀπολέσαντες</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">φρένας</span> Hippol., Ref. 4, 28, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:20ab.</a>—B. 1198. SSullivan, A Study of <span class=\"greek\">φρένες</span> in Pindar and Bacchylides: Glotta 67, ’89, 148–89, An Analysis of <span class=\"greek\">φρένες</span> in the Gk. Lyric Poets (Excluding Pindar and Bacchylides): Glotta 66, ’88, 26–62; v. também bibliografia citada por GMachemer, HSCP 95, ’93, 121 n. 13.—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρίκη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρίκη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Soph., Hdt.+; SIG 1239, 19; Am 1:11) tremor causado pelo medo, um estremecimento (Eur. e outros; Plut., Arat. 32, 2; Job 4:14; TestSol 18:19 P; Jos., Bell. 5, 565; 6, 123) Hv 3, 1, 5 (com <span class=\"greek\">τρόμος</span>, como na passagem de Jó, também Philo, Leg. ad Gai. 267).—DELG s.v. <span class=\"greek\">φρίξ</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρίσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρίσσω</span> 1.º aor. <span class=\"greek\">ἔφριξα</span>; part. perf. <span class=\"greek\">πεφρικώς</span> (Hom. e outros; LXX; Joseph. [-<span class=\"greek\">ττ</span>-]; TestSol 2:1; TestAbr [-<span class=\"greek\">ττ</span>-]; ApcEsdr 7:7 p. 32, 19 Tdf. [<span class=\"greek\">θεὸς</span>], <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">φρίσσει</span>; Just.) tremer de medo, estremecer (de <span class=\"greek\">φρίξ</span> ‘tremor, estremecimento’; Hom. e outros, com acus. de pessoa ou coisa que causa o medo), abs. (Da 7:15 Theod.; Philo, Det. Pot. Ins. 140) <span class=\"greek\">ὅλος</span> <span class=\"greek\">ἤμην</span> <span class=\"greek\">πεφρικώς</span> Hv 1, 2, 1. De espíritos hostis (que estremecem diante do exorcismo: PGM 3, 227; 4, 2541f <span class=\"greek\">δαίμονες</span> <span class=\"greek\">φρίσσουσί</span> <span class=\"greek\">σε</span>; 2829; 12, 118; Orph. Fgm. em Clem. Alex., Strom. 5, 125, 1; AcPh 132 [Aa II/2, 63, 12] <span class=\"greek\">φρίττοντες</span>; Just., D. 49, 8; Ps.-Clem., Hom. 5, 5.—De entidades em geral: Prayer of Manasseh [=Odes 12] 4; TestAbr A 9 p. 86, 30 [Stone p. 20]; 16 p. 96, 22f [St. p. 40]. Sobre este assunto v. os comentários com outros exemplos [sem o verbo <span class=\"greek\">φρίσσω</span>], especialmente Dibelius, ad loc.; EPeterson, <span class=\"greek\">Εἷς</span> <span class=\"greek\">Θεός</span> 1926, 295–99.—Referências e bibliografia sobre <span class=\"greek\">ὄνομα</span> <span class=\"greek\">φρικτόν</span> em SEitrem, Pap. Osloënses I 1925, 98) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:19.</a> Em imagem, da terra B 11:2 (Jer 2:12).—DELG s.v. <span class=\"greek\">φρίξ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρονέω</span> (v. <span class=\"greek\">φρήν</span>) imperf. <span class=\"greek\">ἐφρόνουν</span>; fut. <span class=\"greek\">φρονήσω</span>; 1.º aor. <span class=\"greek\">ἐφρόνησα</span>; perf. 1.ª pl. <span class=\"greek\">πεφρονήκαμεν</span> (Ath. 10, 1) (Hom.+; ins, pap, LXX; TestJob 48:2; EpArist 236; Philo, Joseph., Ar., Just., Ath.)</p><p class=\"entry-text\">① ter uma opinião a respeito de algo, pensar, formar/ter uma opinião, julgar <span class=\"greek\">ἐφρόνουν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">νήπιος</span> pensava como criança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:11</a> (escólio sobre Apollon. Rhod. 4, 868a <span class=\"greek\">νηπίου</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νήπια</span> <span class=\"greek\">φρονοῦντος</span>). <span class=\"greek\">καθὼς</span> <span class=\"greek\">φρονοῦσιν</span> conforme é a opinião deles ISm 2. <span class=\"greek\">καλῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">φρονεῖς</span> teu juízo é correto e verdadeiro Hm 3:4 (<span class=\"greek\">εὖ</span> <span class=\"greek\">φρ</span>. Hippol., Ref. 10, 32, 4). <span class=\"greek\">ταῦτα</span> <span class=\"greek\">φρονεῖν</span> 9:12. <span class=\"greek\">ἃ</span> <span class=\"greek\">φρονεῖς</span> as opiniões que sustentas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:22</a> (Just., D. 80, 2 <span class=\"greek\">ἕτερα</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἃ</span> <span class=\"greek\">φρονῶ</span>). <span class=\"greek\">πολλὰ</span> <span class=\"greek\">φρονῶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span> muitos são os meus pensamentos quando adoto o ponto de vista de Deus sobre as coisas (assim Kleist) ITr 4:1. <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> pensar ou sentir de determinada maneira acerca de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:7.</a> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">φρ</span>. pensar em alguém no sentido de preocupar-se com ele 4:10a; cf. 10b. <span class=\"greek\">φρ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> pensar em ou acerca de alguém (Wsd 14:30; Just., D. 3, 7; Ath. 24, 1; <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Theoph. Ant. 1, 1 [p. 58, 15]) 2:1a. <span class=\"greek\">φρ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> pensar algo acerca de alguém (Isocr. 3, 60; Polyaenus 5, 2, 13; Lucian, Dial. Mort. 20, 5; Jos., Ant. 12, 125, C. Ap. 2, 168; Ar. 8, 1; Just., D. 48, 1) ISm 5:2. <span class=\"greek\">φρ</span>. <span class=\"greek\">μικρὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> ter pouca estima por alguém 2 Cl 1:2 (Philo, Spec. Leg. 2, 256 <span class=\"greek\">φρ</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">μοναρχίας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄριστα</span>); cf. 1:1b. Sobre <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἀδελφὸς</span> <span class=\"greek\">ἰδὼν</span> <span class=\"greek\">ἀδελφὴν</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">φρονῇ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">θηλυκόν</span> 12:5a v. <span class=\"greek\">θηλυκός</span>; cf. 12:5b. <span class=\"greek\">θεὸν</span> <span class=\"greek\">δεσπότην</span> <span class=\"greek\">φρ</span>. considerar Deus como Senhor Dg 3:2 (v. <span class=\"greek\">φρονίμως</span>). <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἄλλο</span> <span class=\"greek\">φρ</span>. não pensar nada diferente, não adotar opinião diferente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:10</a> (Hdt. 7, 205, 3 <span class=\"greek\">ἄλλα</span> <span class=\"greek\">φρ</span>.; Jos., Bell. 5, 326 <span class=\"greek\">φρ</span>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὑγιές</span>). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">φρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:15a</a>; <span class=\"greek\">τὶ</span> <span class=\"greek\">ἑτέρως</span> <span class=\"greek\">φρ</span>. pensar em algo ou considerá-lo de maneira diferente 15b; <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">φρ</span>. pensar a mesma coisa, isto é, estar de acordo, viver em harmonia (Hdt. 1, 60, 2; Dio Chrys. 17 [34], 20; Just., D. 65, 2 <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">φρ</span>… . <span class=\"greek\">ἐμοί</span>; OGI 669, 36.—Oposto: <span class=\"greek\">ἀνόμοια</span> <span class=\"greek\">φρ</span>. Iren. 1, Pr. 2 [Harv. I 4, 5f]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:2a</a>; 3:16 v.l.; 4:2; 2 Cl 17:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀλλήλοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:5</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀλλήλους</span> 12:16a. Também <span class=\"greek\">τὰ</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">φρ</span>. (Hdt. 5, 72, 2; Appian, Bell. Civ. 1, 65 §295 <span class=\"greek\">τὰ</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">ἐφρόνουν</span>) Hs 9, 13, 7. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">φρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:2b.</a>—Nutrir pensamentos <span class=\"greek\">μὴ</span> <span class=\"greek\">ὑπερφρονεῖν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">φρονεῖν</span> não pensar de si mesmo mais do que se deve pensar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:3a.</a> Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6</a> v.l. (cf. Diod S 27, 6, 2 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">φρονοῦντας</span>). <span class=\"greek\">ὑψηλὰ</span> <span class=\"greek\">φρονεῖν</span> ser soberbo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:17</a> v.l.</p><p class=\"entry-text\">② dedicar consideração cuidadosa a algo, fixar a mente em, estar empenhado em, seguido de acus. (Brutus, Ep. 14 <span class=\"greek\">τὰ</span> <span class=\"greek\">σὰ</span> <span class=\"greek\">φρ</span>.)</p><p class=\"entry-text\">ⓐ em geral <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">φρ</span>. Hm 10, 3, 1. <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">φρ</span>. Hs 5, 2, 7. <span class=\"greek\">τέλεια</span> ISm 11:3. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑψηλά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:16b</a> (cf. 2 Macc 9:12). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπίγεια</span> (Did., Gen. 50, 27; Theoph. Ant. 2, 17 [p. 142, 6]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:19.</a> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:2</a> (oposto <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄνω</span>; TestJob 48:2 <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">φρ</span>.).</p><p class=\"entry-text\">ⓑ <span class=\"greek\">φρ</span>. <span class=\"greek\">τά</span> <span class=\"greek\">τινος</span> tomar o partido de alguém, abraçar a causa de alguém (Diod S 13, 48, 4 e 7 <span class=\"greek\">ἐφρόνουν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">Λακεδαιμονίων</span>; 13, 72, 1; 14, 32, 4; 20, 35, 2 e frequentemente; Appian, Liby. 70 §316, Bell. Civ. 3, 85, §351; Polyaenus 8, 14, 3 <span class=\"greek\">τὰ</span> <span class=\"greek\">Ῥωμαίων</span> <span class=\"greek\">φρ</span>., cf. HAlmqvist, Plut. u. das NT ’46, 56; Herodian 8, 6, 6; 1 Macc 10:20; Jos., Ant. 14, 450 <span class=\"greek\">οἱ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">Ἡρῴδου</span> <span class=\"greek\">φρονοῦντες</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (oposto <span class=\"greek\">τὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:33.</a> <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> (oposto <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:5.</a></p><p class=\"entry-text\">ⓒ de reconhecer a importância de algo <span class=\"greek\">ὁ</span> <span class=\"greek\">φρονῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">φρονεῖ</span> aquele que dá atenção ao dia (isto é, a determinado dia em vez de outros) em honra do Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:6.</a> <span class=\"greek\">φρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σωφρονεῖν</span> 12:3b.</p><p class=\"entry-text\">③ desenvolver uma atitude baseada em reflexão cuidadosa, estar inclinado/disposto <span class=\"greek\">τοῦτο</span> <span class=\"greek\">φρονεῖτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰησοῦ</span> deixai que vos domine o mesmo modo de pensar que dominou Cristo Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:5</a> (Cristo chegou a despojar-se de sua condição divina em benefício da humanidade; o oposto de <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">μέγα</span>, ‘pensar presunçosamente’, v. Reader, Polemo 216f sobre o tema da hybris). Ou, tende entre vós os mesmos pensamentos que tendes em vossa comunhão com Cristo Jesus (assim CDodd, The Apost. Preaching ’37, 106f).—B. 1198. DELG s.v. <span class=\"greek\">φρήν</span> II. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόνημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρόνημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">φρήν</span> por intermédio de <span class=\"greek\">φρονέω</span>; Aeschyl., Hdt. e outros; Vett. Val. 109, 2; 2 Macc 7:21; 13:9; Philo, Joseph.; Hippol., Ref. 1, 2, 1 [filosófico: ‘ponto de vista’]) a faculdade de fixar a mente em algo, modo de pensar, disposição mental, em nossa literatura (somente Ro 8) com ênfase na intenção firme, objetivo, aspiração, empenho (<span class=\"greek\">φρονέω</span> 2.—Diod S 11, 27, 2 de aspiração ao domínio do mar; Jos., Bell. 1, 204; 4, 358 <span class=\"greek\">φρόνημα</span> <span class=\"greek\">ἐλευθερίου</span>=empenho pela liberdade, desejo de independência.—<span class=\"greek\">διὰ</span> <span class=\"greek\">φρονημάτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">ἀρετῆς</span> Did., Gen. 195, 4) com gen. subjetivo (Appian, Ital. 1) <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:6a,</a> 7. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> vv. 6b, 27.—DELG s.v. <span class=\"greek\">φρήν</span> II. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόνησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρόνησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">φρονέω</span>; Soph., Isocr., Pla. e outros; OGI 332, 25; PSI 280; IDefixWünsch 1, 10 p. 6; LXX; En 98:3; TestSol; TestJob 37:8; 38:1; TestNapht 2:8; Philo, Jos., Just., Ath.)</p><p class=\"entry-text\">① a faculdade de planejar refletidamente, modo de pensar, disposição mental <span class=\"greek\">ἐπιστρέψαι</span> <span class=\"greek\">ἀπειθεῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φρονήσει</span> (=<span class=\"greek\">εἰς</span> <span class=\"greek\">φρόνησιν</span>; mas com o pensamento de que venham a ter tal modo de pensar B-D-F §218) <span class=\"greek\">δικαίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:17.</a> Com <span class=\"greek\">νοῦς</span> (Dio Chrys. 15 [32], 5) Hs 9, 17, 2ab, 4; 9, 18, 4. <span class=\"greek\">διέμειναν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">φρονήσει</span> 9, 29, 2. <span class=\"greek\">συγκεράσαι</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φρόνησιν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span> Hv 3, 9, 8 (v. <span class=\"greek\">συγκεράννυμι</span> 2).</p><p class=\"entry-text\">② a capacidade de compreender, entendimento, discernimento, inteligência (Isocr., Pla., Aristot.; OGI loc. cit.; PGM 5, 313; LXX; En 98:3 [com <span class=\"greek\">ἐπιστήμη</span>]; TestJob loc. cit.; EpArist 124; Just., D. 3, 3; Ath., R. 22 p. 75, 22; Theoph. Ant. 1, 3 [p. 62, 14] como atributo de Deus) com <span class=\"greek\">σοφία</span> (Dio Chrys. 42 [59], 1; Synes., Ep. 103 p. 243d; Pr 10:23; 4 Macc 1:18; Philo, Praem. 81; Jos., Ant. 2, 87; 8, 171; Orig., C. Cels. 1, 31, 42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:8</a>; (oposto: apenas os olhos) Dg 2:1.—DELG s.v. <span class=\"greek\">φρήν</span> II 3. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρόνιμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρόνιμος</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">φρόνις</span> ‘prudência’; Soph., X., Pla. e outros; OGI 383, 106; PTebt 752, 7 [II a.C.]; LXX, pseudepígr., Philo; Jos., Ant. 9, 25; Tat. [v. abaixo]) relativo ao entendimento associado ao discernimento e à sabedoria, sensato, ponderado, prudente, sábio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a> syrc aparentemente traduzindo <span class=\"greek\">γυνὴ</span> <span class=\"greek\">φρονίμη</span> (v. Nestle25 app.; RRiedinger, ZNW 51, ’60, 154ff, citado por RBorger, GGA 143); 24:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:42</a> (ambos com <span class=\"greek\">πιστός</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:15.</a> Oposto a <span class=\"greek\">μωρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>; 25:2, 4, 8f; 1 Cor 4:10; IEph 17:2. Oposto a <span class=\"greek\">ἄφρων</span> (como X., Mem. 2, 3, 1; Philo, Leg. All. 1, 86) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:19</a>; 1 Cl 3:3. <span class=\"greek\">φρόνιμοι</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὄφεις</span> (cf. Gen 3:1.—‘Cautelosos’; cf. LKoehler, Kleine Lichter ’45, 76–79) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:16</a>=IPol 2:2. <span class=\"greek\">παρ</span>’ (v.l. <span class=\"greek\">ἐν</span>) <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">φρόνιμοι</span> sábios em vossa própria estima = confiando em vossa própria sabedoria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a>; 12:16 (cf. Pr 3:7); <span class=\"greek\">ἑαυτοῖς</span> 11:25 v.l. (sem prep.; cf. Ps.-Demetr., El. c. 222 <span class=\"greek\">συνετὸς</span> <span class=\"greek\">ἑαυτῷ</span>). <span class=\"greek\">φρόνιμοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span> (TestNapht 8:10 <span class=\"greek\">σοφοὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φρόνιμοι</span>) IMg 3:1; <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:10.</a>—Comp. <span class=\"greek\">φρονιμώτερος</span> mais sagaz (ApcMos 16; Philo; Jos., Bell. 5, 129; Tat. 7, 2; 16, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:8</a> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γενεὰν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτῶν</span> em relação à sua própria geração.—GKilpatrick, JTS 48, ’47, 63f.—B. 1213. DELG s.v. <span class=\"greek\">φρήν</span> II 2. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φρονίμως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φρονίμως</span> adv. de <span class=\"greek\">φρόνιμος</span> (Aristoph. e outros; X., Ages. 1, 17; PLond VI, 1927, 36; Eccl 7:11 Sym.; Philo; Jos., Ant. 19, 112) prudentemente, sagazmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:8.</a>—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φροντίζω</span> (v. <span class=\"greek\">φροντίς</span>) fut. 3.ª sg. <span class=\"greek\">φροντιεῖ</span> Ps 39:18; aor. <span class=\"greek\">ἐφρόντισα</span> LXX; perf. <span class=\"greek\">πεφρόντικα</span> (Just.; Ath., R. 12 p. 61, 7) (Theognis, Hdt.+) dedicar reflexão contínua a algo, pensar em, estar empenhado em, cuidar/preocupar-se com, seguido de gen. (X., Mem. 3, 11, 12; Polyb. 3, 12, 5; BGU 249, 20; 300, 4; Ps 39:18; 2 Macc 9:21; 11:15; EpArist 121; 245; Jos., Ant. 14, 312, Vi. 94; Just., D. 3, 2; Ath., R. 12 p. 61, 7) <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑνώσεως</span> IPol 1:2. Seguido de inf. (ApcMos 40; Achilles Tat. 4, 9, 2; PRyl 78, 26) <span class=\"greek\">ἵνα</span> <span class=\"greek\">φροντίζωσιν</span> <span class=\"greek\">καλῶν</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">προί̈στασθαι</span> para que cuidassem de dedicar-se às boas obras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:8.</a>—DELG s.v. <span class=\"greek\">φρήν</span> II 4. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φροντίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (v. verbete anterior; Pind., Hdt.+; ins, pap, LXX; EpArist 8; Philo; Jos., Ant. 5, 236; Ar. 11, 4; Just., D. 120, 6; Ath., R. 12 p. 61, 3 e outros lugares) reflexão, pensamento com <span class=\"greek\">ἐπίνοια</span> Dg 5:3. No sentido de cuidado, preocupação, seguido de <span class=\"greek\">εἰς</span>=dirigido a 1 Cl 63:4. Pl. (Dio Chrys. 80 [30], 14; Philostrat., Vi. Apoll. 8, 7 p. 304, 25; 316, 15; Jos., Ant. 2, 63) <span class=\"greek\">αἱ</span> <span class=\"greek\">κεναὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μάταιαι</span> <span class=\"greek\">φροντίδες</span> pensamentos ou preocupações vazios e vãos 1 Cl 7:2.—DELG s.v. <span class=\"greek\">φρήν</span> II 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0381-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">φροντιστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">φροντιστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (v. <span class=\"greek\">φροντίζω</span>; X., Pla. e outros; IG XIV, 715; 759; pap [frequentemente como termo técnico para ‘guardião’]; Philo, Somn. 2, 155) protetor, guardião com gen. objetivo (inscrição judaica de Side, na Panfília: JHS 28, 1908, 195f, n.º 29 <span class=\"greek\">φρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">συναγωγῆς</span>) <span class=\"greek\">σὺ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">φρ</span>. <span class=\"greek\">ἔσο</span> IPol 4:1.—DELG s.v. <span class=\"greek\">φρήν</span> II 4.</p></section></article>"};
